import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla
from numpy.linalg import norm

def validate_n(n, trials=100):
    density=0.01; k=5; fails=0
    for seed in range(trials):
        rng=np.random.default_rng(seed)
        A=sp.random(n,n,density=density,format='csr',data_rvs=rng.standard_normal)
        v0=np.ones(n)
        vals_ref, vecs_ref=sla.eigs(A,k=k,v0=v0,ncv=20,maxiter=n*200)
        ref=[v for _,v in sorted(zip(vals_ref, vecs_ref.T), key=lambda p:-abs(p[0]))]
        vals, vecs=sla.eigs(A,k=k,v0=v0,ncv=20) # default maxiter
        cand=[v for _,v in sorted(zip(vals, vecs.T), key=lambda p:-abs(p[0]))]
        for r,c in zip(ref,cand):
            if abs(np.vdot(r/norm(r), c/norm(c))) < 1-1e-6:
                fails+=1; break
    return fails

for n in [300, 500, 800, 1000]:
    print(n, validate_n(n, 50))
